#!/usr/bin/env node
// Generates web/src/api/schema.gen.ts from Core's OpenAPI document.
//
// Usage: node tools/openapi/gen.mjs [source] [--check]
//   source   file path or URL; default $HAZELMINX_OPENAPI, then http://127.0.0.1:9800/management/v1/openapi.json
//   --check  exit 1 if the generated file would change (for CI), without writing it
import { readFile, writeFile } from "node:fs/promises";
import { fileURLToPath } from "node:url";
import openapiTS, { astToString } from "openapi-typescript";

const args = process.argv.slice(2);
if (args.includes("--help") || args.includes("-h")) {
  console.log("Usage: node tools/openapi/gen.mjs [source-file-or-url] [--check]");
  process.exit(0);
}
const check = args.includes("--check");
const source =
  args.find((a) => !a.startsWith("--")) ??
  process.env.HAZELMINX_OPENAPI ??
  "http://127.0.0.1:9800/management/v1/openapi.json";
const out = fileURLToPath(new URL("../../src/api/schema.gen.ts", import.meta.url));

let doc;
try {
  const text = /^https?:\/\//.test(source)
    ? await fetch(source).then((r) => {
        if (!r.ok) throw new Error(`HTTP ${r.status} from ${source}`);
        return r.text();
      })
    : await readFile(source, "utf8");
  doc = JSON.parse(text);
} catch (e) {
  console.error(`Cannot read the OpenAPI document from ${source}: ${e.message}`);
  process.exit(2);
}

const ast = await openapiTS(doc, { alphabetize: true });
const generated = `// Generated by tools/openapi/gen.mjs from Core's OpenAPI document. Do not edit.\n${astToString(ast)}`;

if (check) {
  const current = await readFile(out, "utf8").catch(() => "");
  if (current !== generated) {
    console.error("src/api/schema.gen.ts is out of date; run: vpr api:gen");
    process.exit(1);
  }
  console.log("src/api/schema.gen.ts is up to date");
} else {
  await writeFile(out, generated);
  console.log(`wrote ${out}`);
}
